solution.solution.cpp:
#include <random>

int randomBetween(std::mt19937& rng, int low, int high)
{
    std::uniform_int_distribution<int> pick{ low, high };
    return pick(rng);
}

unitTests:
TEST("stays inside the range") {
    std::mt19937 rng{ 99 };
    bool ok{ true };
    for (int i{ 0 }; i < 5000; ++i) { const int r{ randomBetween(rng, 10, 20) }; if (r < 10 || r > 20) ok = false; }
    CHECK(ok);
}
TEST("both ends can come up") {
    std::mt19937 rng{ 4 };
    bool sawLow{ false }, sawHigh{ false };
    for (int i{ 0 }; i < 5000; ++i) { const int r{ randomBetween(rng, -3, 3) }; if (r == -3) sawLow = true; if (r == 3) sawHigh = true; }
    CHECK(sawLow); CHECK(sawHigh);
}
TEST("a range of one value") { std::mt19937 rng{ 1 }; CHECK_EQ(randomBetween(rng, 7, 7), 7); }

